<script setup lang="ts">definePageMeta({layout:'admin'});const route=useRoute(),router=useRouter();const f=reactive({from:String(route.query.from||''),to:String(route.query.to||''),product:String(route.query.product||''),category:String(route.query.category||''),type:String(route.query.type||''),keyword:String(route.query.keyword||''),page:Number(route.query.page)||1});watch(f,()=>router.replace({query:Object.fromEntries(Object.entries(f).filter(([,v])=>v&&v!==1))}));const {data}=await useFetch('/api/admin/reports/inventory',{query:f,transform:(r:any)=>r});const {data:products}=await useFetch('/api/admin/inventory/overview',{transform:(r:any)=>r.data});const {data:cats}=await useFetch('/api/admin/categories',{transform:(r:any)=>r.data});const label:any={IN:'Barang Masuk',OUT:'Barang Keluar',ADJUSTMENT_IN:'Penyesuaian Tambah',ADJUSTMENT_OUT:'Penyesuaian Kurang'};const date=(v:string)=>new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));const csv=computed(()=>'/api/admin/reports/inventory.csv?'+new URLSearchParams(Object.fromEntries(Object.entries(f).filter(([,v])=>v).map(([k,v])=>[k,String(v)]))).toString());function clear(){Object.assign(f,{from:'',to:'',product:'',category:'',type:'',keyword:'',page:1})}</script><template><div class="admin-page"><AdminPageHeader title="Laporan stok" description="Telusuri mutasi masuk, keluar, dan penyesuaian."><a class="btn btn-primary" :href="csv">Export CSV</a></AdminPageHeader><div class="panel report-filter"><input v-model="f.from" class="field" type="date" aria-label="Tanggal awal"><input v-model="f.to" class="field" type="date" aria-label="Tanggal akhir"><select v-model="f.product" class="field"><option value="">Semua produk</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} — {{p.name}}</option></select><select v-model="f.category" class="field"><option value="">Semua kategori</option><option v-for="c in cats" :key="c.id" :value="c.slug">{{c.name}}</option></select><select v-model="f.type" class="field"><option value="">Semua jenis</option><option v-for="(v,k) in label" :key="k" :value="k">{{v}}</option></select><input v-model="f.keyword" class="field" placeholder="Cari referensi"><button class="btn btn-outline" @click="clear">Bersihkan</button></div><div class="summary"><MetricCard label="Total barang masuk" :value="data?.meta.summary.totalIn||0"/><MetricCard label="Total barang keluar" :value="data?.meta.summary.totalOut||0"/><MetricCard label="Transaksi mutasi" :value="data?.meta.summary.transactions||0"/></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Referensi</th><th>Produk</th><th>Jenis</th><th>Qty</th><th>Sebelum</th><th>Sesudah</th><th>Admin</th></tr></thead><tbody><tr v-for="x in data?.data" :key="x.id"><td>{{date(x.movementAt)}}</td><td>{{x.reference||'—'}}</td><td><b>{{x.productName}}</b><br><small>{{x.sku}} · {{x.categoryName}}</small></td><td>{{label[x.movementType]}}</td><td>{{x.quantity}}</td><td>{{x.beforeStock}}</td><td>{{x.afterStock}}</td><td>{{x.adminName}}</td></tr><tr v-if="!data?.data.length"><td colspan="8" class="muted">Belum ada mutasi yang cocok.</td></tr></tbody></table></div></div></template><style scoped>.report-filter{padding:1rem;display:grid;grid-template-columns:repeat(4,1fr);gap:.6rem}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}@media(max-width:900px){.report-filter{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.report-filter,.summary{grid-template-columns:1fr}}</style>
